  h += '        .q-card .q-result{font-size:.78em;font-weight:600;margin-top:6px}\n';
  h += '        .q-card .q-result.correct{color:var(--emerald)}\n';
  h += '        .q-card .q-result.wrong{color:#ef4444}\n';
